package com.abluepoint.summer.sample.physicalconnection;
import com.abluepoint.summer.common.response.api.*;import com.abluepoint.summer.mvc.response.api.RawResponse;import com.abluepoint.summer.mvc.request.api.RequestIdAccessor;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @PreAuthorize("isAuthenticated()") class PhysicalExecutionController{final PhysicalExecutionService s;final RequestIdAccessor r;PhysicalExecutionController(PhysicalExecutionService s,RequestIdAccessor r){this.s=s;this.r=r;}@PostMapping(value="/internal/v1/connections/{connectionId}/tools/{tool}:invoke",consumes=MediaType.APPLICATION_JSON_VALUE)@RawResponse ResponseEntity<ApiResponse<PhysicalExecutionView>> invoke(@PathVariable String connectionId,@PathVariable String tool,@RequestBody PhysicalInvokeRequest q,Authentication a){try{return body(HttpStatus.OK,s.invoke(connectionId,tool,a instanceof org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken j?j.getToken().getClaimAsString("connection_service_id"):null,q,a));}catch(Exception e){return err(e);}}private<T>ResponseEntity<ApiResponse<T>>body(HttpStatus h,T v){return ResponseEntity.status(h).header("X-Request-Id",r.currentRequestId()).body(ApiResponse.success(v,r.currentRequestId()));}private<T>ResponseEntity<ApiResponse<T>>err(Exception e){HttpStatus h=HttpStatus.INTERNAL_SERVER_ERROR;String c="SUMMER_INTERNAL_ERROR";if(e instanceof org.springframework.security.access.AccessDeniedException){h=HttpStatus.FORBIDDEN;c="SUMMER_FORBIDDEN";}else if(e instanceof PhysicalExecutionValidationException){h=HttpStatus.BAD_REQUEST;c="SUMMER_EXECUTION_INVALID";}else if(e instanceof PhysicalExecutionConflictException||e.getClass().getSimpleName().contains("Conflict")){h=HttpStatus.CONFLICT;c="SUMMER_EXECUTION_CONFLICT";}return ResponseEntity.status(h).header("X-Request-Id",r.currentRequestId()).body(ApiResponse.failure(new ApiError(c,e.getMessage(),List.of()),r.currentRequestId()));}}
